Translate the following GNU C++17 code to Java 8 code. The code reads and writes I/O from the console. Your translated code should have the exact same functionality as the given code, meaning that it should have the same output for any given input.
Print your translated code and also the confidence score you give to your translation. The confidence score should be a number between 0 and 1. The format of the output should be:
<translated_code>
<your_translated_code>
</translated_code>
<confidence>
<your_confidence_score>
</confidence>
Do not provide any other text or markdown fences.

Here is the original GNU C++17 code you have to translate:
<original_code>
#include <iostream>
#include <vector>
using namespace std;

long long A[20];

long long solve(int position, long long number) {
    if (position == 0)
        return number == 0 ? 0 : 100000000;
    if (number < 0) number = -number;
    long long quotient = number / A[position];
    long long optionA = solve(position - 1, number - quotient * A[position]) + quotient * position;
    long long optionB = solve(position - 1, number - (quotient + 1) * A[position]) + (quotient + 1) * position;
    return min(optionA, optionB);
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    long long n;
    cin >> n;
    A[0] = 1;
    for (int i = 1; i <= 16; ++i)
        A[i] = A[i - 1] * 10 + 1;
    cout << solve(16, n) << '\n';
    return 0;
}
</original_code>
